package local.knowledge.library;

import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.OffsetDateTime;
import java.util.*;
import java.util.concurrent.Executor;
import java.util.stream.Collectors;
import org.apache.tika.Tika;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.FileSystemResource;
import org.springframework.core.io.Resource;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import jakarta.annotation.PostConstruct;
import org.springframework.web.multipart.MultipartFile;

@Service
public class LibraryService {
  private static final long MAX = 50L * 1024 * 1024;
  private static final Set<String> EXT = Set.of("pdf","docx","txt","md");
  private final JdbcTemplate db; private final Path root; private final Executor executor; private final Tika tika = new Tika();
  public LibraryService(JdbcTemplate db, @Value("${DATA_ROOT:./data}") String dataRoot) { this.db=db; this.root=Path.of(dataRoot).toAbsolutePath().normalize(); this.executor=Runnable::run; }
  @PostConstruct void recover() { try { db.queryForList("select id,storage_key from document where status='PROCESSING'").forEach(r -> { Path p=root.resolve(String.valueOf(r.get("STORAGE_KEY"))).normalize(); if(Files.exists(p)) process(String.valueOf(r.get("ID")),p); else db.update("update document set status='FAILED_RETRYABLE',failure_code='FILE_MISSING',failure_message='原文件不存在' where id=?",r.get("ID")); }); } catch(Exception ignored) { } }
  private Map<String,Object> row(Map<String,Object> r) { return r; }
  private void existsBase(String id) { if (db.queryForObject("select count(*) from knowledge_base where id=? and deleted_at is null",Integer.class,id)==0) throw new LibraryException(HttpStatus.NOT_FOUND,"KB_NOT_FOUND","知识库不存在"); }
  private void existsDoc(String id) { if (db.queryForObject("select count(*) from document where id=?",Integer.class,id)==0) throw new LibraryException(HttpStatus.NOT_FOUND,"DOCUMENT_NOT_FOUND","文档不存在"); }
  public Map<String,Object> bases(int page,int size) { size=Math.min(Math.max(size,1),100); var rows=db.queryForList("select * from knowledge_base where deleted_at is null order by updated_at desc limit ? offset ?",size,page*size); return Map.of("items",rows,"page",page,"pageSize",size); }
  public Map<String,Object> createBase(String name,String desc) { name=name==null?"":name.trim(); if(name.isBlank()||name.length()>120) throw new LibraryException(HttpStatus.BAD_REQUEST,"KB_NAME_INVALID","名称不能为空且不超过120个字符"); if(db.queryForObject("select count(*) from knowledge_base where name=? and deleted_at is null",Integer.class,name)>0) throw new LibraryException(HttpStatus.CONFLICT,"KB_NAME_CONFLICT","知识库名称已存在"); String id=UUID.randomUUID().toString(), now=OffsetDateTime.now().toString(); db.update("insert into knowledge_base(id,name,description,created_at,updated_at) values(?,?,?,?,?)",id,name,desc==null?"":desc,now,now); return base(id); }
  public Map<String,Object> base(String id) { existsBase(id); return db.queryForMap("select * from knowledge_base where id=?",id); }
  public Map<String,Object> editBase(String id,Map<String,String> b) { existsBase(id); String name=b.containsKey("name")?b.get("name").trim():null; if(name!=null&&(name.isBlank()||name.length()>120)) throw new LibraryException(HttpStatus.BAD_REQUEST,"KB_NAME_INVALID","名称不能为空且不超过120个字符"); if(name!=null&&db.queryForObject("select count(*) from knowledge_base where name=? and id<>? and deleted_at is null",Integer.class,name,id)>0) throw new LibraryException(HttpStatus.CONFLICT,"KB_NAME_CONFLICT","知识库名称已存在"); db.update("update knowledge_base set name=coalesce(?,name), description=coalesce(?,description), updated_at=? where id=?",name,b.get("description"),OffsetDateTime.now().toString(),id); return base(id); }
  public void deleteBase(String id,boolean confirm) { existsBase(id); int n=db.queryForObject("select count(*) from document where knowledge_base_id=? and status<>'DELETED'",Integer.class,id); if(n>0&&!confirm) throw new LibraryException(HttpStatus.CONFLICT,"KB_DELETE_CONFIRM_REQUIRED","该知识库包含"+n+"份文档，请确认删除"); db.queryForList("select id from document where knowledge_base_id=?",id).forEach(r->deleteDocument((String)r.get("id"))); db.update("update knowledge_base set deleted_at=?,updated_at=? where id=?",OffsetDateTime.now().toString(),OffsetDateTime.now().toString(),id); }
  public Map<String,Object> documents(String kb,int page,int size,String status,String query) { existsBase(kb); size=Math.min(Math.max(size,1),100); String s="select * from document where knowledge_base_id=? and status<>'DELETED'"; List<Object> args=new ArrayList<>(List.of(kb)); if(status!=null&&!status.isBlank()){s+=" and status=?";args.add(status);} if(query!=null&&!query.isBlank()){s+=" and original_name like ?";args.add("%"+query+"%");} s+=" order by created_at desc limit ? offset ?";args.add(size);args.add(page*size); return Map.of("items",db.queryForList(s,args.toArray()),"page",page,"pageSize",size); }
  public Map<String,Object> upload(String kb,MultipartFile file) throws IOException { existsBase(kb); if(file==null||file.isEmpty()) throw new LibraryException(HttpStatus.BAD_REQUEST,"FILE_EMPTY","文件为空"); if(file.getSize()>MAX) throw new LibraryException(HttpStatus.BAD_REQUEST,"FILE_TOO_LARGE","文件超过50MB"); String name=Optional.ofNullable(file.getOriginalFilename()).orElse("file"); String ext=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase():""; if(!EXT.contains(ext)) throw new LibraryException(HttpStatus.BAD_REQUEST,"FILE_TYPE_UNSUPPORTED","仅支持 PDF、DOCX、TXT、Markdown"); byte[] bytes=file.getBytes(); String id=UUID.randomUUID().toString(), key="raw/"+id+"/"+id+"."+ext; Path p=root.resolve(key).normalize(); if(!p.startsWith(root)) throw new LibraryException(HttpStatus.BAD_REQUEST,"PATH_INVALID","文件路径无效"); Files.createDirectories(p.getParent()); Files.write(p,bytes,StandardOpenOption.CREATE_NEW); String now=OffsetDateTime.now().toString(); db.update("insert into document(id,knowledge_base_id,original_name,media_type,size_bytes,sha256,storage_key,status,parser_version,created_at,updated_at) values(?,?,?,?,?,?,?,?,?,?,?)",id,kb,name,Optional.ofNullable(file.getContentType()).orElse("application/octet-stream"),bytes.length,sha(bytes),key,"PROCESSING","tika-3.2.2",now,now); executor.execute(()->process(id,p)); return document(id); }
  private String sha(byte[] b){try{var d=MessageDigest.getInstance("SHA-256");return HexFormat.of().formatHex(d.digest(b));}catch(Exception e){throw new IllegalStateException(e);}}
  private void process(String id,Path p){ try { String text=tika.parseToString(p.toFile()); if(text==null||text.isBlank()) throw new IllegalArgumentException("EMPTY_TEXT"); db.update("delete from document_chunk where document_id=?",id); int n=0; for(int i=0;i<text.length();i+=1200){String c=text.substring(i,Math.min(text.length(),i+1200)); db.update("insert into document_chunk(id,document_id,ordinal,chunk_text,start_offset,pipeline_version) values(?,?,?,?,?,?)",UUID.randomUUID().toString(),id,n++,c,i,"tika-v1");} db.update("update document set status='READY',failure_code=null,failure_message=null,updated_at=? where id=?",OffsetDateTime.now().toString(),id); } catch(Exception e){ db.update("update document set status='FAILED_RETRYABLE',failure_code='PARSE_FAILED',failure_message=?,attempt_count=attempt_count+1,updated_at=? where id=?",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage(),OffsetDateTime.now().toString(),id); } }
  public Map<String,Object> document(String id){existsDoc(id);return db.queryForMap("select * from document where id=?",id);}
  public Map<String,Object> preview(String id){existsDoc(id); var d=document(id); if(!"READY".equals(d.get("STATUS"))&&!"READY".equals(d.get("status"))) throw new LibraryException(HttpStatus.CONFLICT,"DOCUMENT_NOT_READY","文档尚未处理完成"); var rows=db.queryForList("select chunk_text,page_number,section_name from document_chunk where document_id=? order by ordinal",id); return Map.of("documentId",id,"chunks",rows,"text",rows.stream().map(x->String.valueOf(x.getOrDefault("CHUNK_TEXT",x.get("chunk_text")))).collect(Collectors.joining("\n"))); }
  public record Download(String name,Resource resource){}
  public Download download(String id)throws IOException{existsDoc(id);var d=document(id);Path p=root.resolve(String.valueOf(d.getOrDefault("STORAGE_KEY",d.get("storage_key")))).normalize();if(!p.startsWith(root)||!Files.exists(p))throw new LibraryException(HttpStatus.NOT_FOUND,"FILE_MISSING","原文件不存在");return new Download(String.valueOf(d.getOrDefault("ORIGINAL_NAME",d.get("original_name"))),new FileSystemResource(p));}
  public Map<String,Object> retry(String id){existsDoc(id);var d=document(id); if(!"FAILED_RETRYABLE".equals(d.getOrDefault("STATUS",d.get("status")))) throw new LibraryException(HttpStatus.CONFLICT,"RETRY_NOT_ALLOWED","当前状态不能重试");Path p=root.resolve(String.valueOf(d.getOrDefault("STORAGE_KEY",d.get("storage_key")))); db.update("update document set status='PROCESSING',failure_code=null,failure_message=null,updated_at=? where id=?",OffsetDateTime.now().toString(),id); executor.execute(()->process(id,p));return document(id);}
  public void deleteDocument(String id){existsDoc(id);var d=document(id);db.update("delete from document_chunk where document_id=?",id);db.update("update document set status='DELETED',updated_at=? where id=?",OffsetDateTime.now().toString(),id);try{Files.deleteIfExists(root.resolve(String.valueOf(d.getOrDefault("STORAGE_KEY",d.get("storage_key")))));}catch(IOException ignored){}}
}
